$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
$path=Join-Path (Get-Location) 'Documentations\Chapter 3.docx'
$z=[IO.Compression.ZipArchive]::new([IO.File]::Open($path,'Open','ReadWrite'),[IO.Compression.ZipArchiveMode]::Update)
try {
$e=$z.GetEntry('word/document.xml');$r=[IO.StreamReader]::new($e.Open());$d=[Xml.XmlDocument]::new();$d.PreserveWhitespace=$true;$d.LoadXml($r.ReadToEnd());$r.Dispose()
$n=[Xml.XmlNamespaceManager]::new($d.NameTable);$n.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
function Txt($p){return ($p.SelectNodes('.//w:t',$n)|ForEach-Object {$_.InnerText}) -join ''}
function Put($p,$text){$ts=$p.SelectNodes('.//w:t',$n);$ts[0].InnerText=$text;for($i=1;$i -lt $ts.Count;$i++){$ts[$i].InnerText=''}}
function After($anchor,$texts){foreach($text in $texts){$p=$anchor.CloneNode($true);Put $p $text;[void]$anchor.ParentNode.InsertAfter($p,$anchor);$anchor=$p}}
# Keep the field purpose brief without changing the type, limit, or key columns.
$tables=@($d.SelectNodes('//w:body/w:tbl',$n));$count=0
foreach($table in $tables|Select-Object -Skip 5){foreach($row in $table.SelectNodes('w:tr',$n)|Select-Object -Skip 1){$cell=$row.SelectNodes('w:tc',$n)[4];$text=Txt $cell;$first=([regex]::Split($text,'(?<=\.)\s+',2))[0];if($text -match 'The column is required at database level\.'){$first+=' Required.'}elseif($text -match 'The column permits NULL'){$first+=' Nullable.'};Put $cell $first;$count++}}
$paragraphs=@($d.SelectNodes('//w:body/w:p',$n))
foreach($p in $paragraphs){$t=(Txt $p).Trim()
if($t.StartsWith('Figure 2 shows the exchange of data')){
 Put $p '            Figure 2 presents the boundary of IronGrind using Gane-Sarson notation. The numbered rounded process represents the entire membership and operations system, while the rectangular external entities identify the Member / Applicant, Administrator, and Authorized Staff. Named arrows show the information submitted to the system and the information returned to each actor. The diagram is a context view rather than an internal design: it intentionally does not display individual database tables, authentication components, or detailed subprocesses. Those internal responsibilities are explained in the Level 1 DFD.'
 After $p @(
 '            The Member / Applicant exchanges information relating to registration, account access, membership, and personal self-service. An applicant submits registration details and receives the status of the application. A registered member can retrieve their own membership information, QR code, attendance history, and active product catalog, submit a renewal request, and update their own permitted personal details. These flows describe access to the member’s own information; they do not give a member access to another person’s records or to administrator functions.',
 '            The Administrator exchanges review decisions, membership-operation inputs, inventory and sales information, staff-account controls, phone-pairing requests, report queries, and activity-log filters. The system returns the records and confirmations needed for those operations. Administrator access to a member’s personal profile is read-only: viewing the information does not permit editing the member’s personal details. Membership approval, renewal, and plan changes are separate operational actions and should not be interpreted as personal-profile editing.',
 '            Authorized Staff exchange only the information required by their assigned attendance and counter tasks. These tasks include QR attendance, walk-in registration, direct membership renewal, active-member plan changes, product-sale recording, and review of their own product sales. A counter search returns limited details needed to select the correct member; it is not a member-profile viewing function. Staff cannot view or edit member profiles, review online applications, maintain inventory, manage staff accounts or phone pairings, or access administrator reports and activity logs. Walk-in customers transact through an operator rather than acting as direct system users, and transaction confirmations do not represent receipts issued to customers.'
 )
}
if($t.StartsWith('Figure 3a-e uses Gane-Sarson notation')){
 Put $p '       Figure 3a-e expands the context process into nine functional processes using Gane-Sarson notation. The five panels are continuations of one Level 1 model, not five separate systems. Each rounded process box has a distinct number and a name identifying the work it performs. Rectangles identify external actors, while the open-ended data-store symbols separate the store identifier from its name. Every arrow is directional and is labeled with the information exchanged. Reading the actor, process, and store together explains who initiates an operation, what the system does with the input, and where the resulting information is retrieved or recorded.'
 After $p @(
 '       Store identifiers remain consistent across all panels. D0 represents managed authentication accounts, D1 profiles, D2 membership applications, D3 members, D4 attendance, D5 products, D6 sales, D7 sale items, D8 membership history, and D9 activity logs. D10 represents phone-pairing policy, D11 pairing sessions, and D13 private attendance scan requests. D12 is reserved for the retained scan-event table in the physical schema and is not shown as an active frontend feature. Repeated symbols refer to the same actor or store. The D2-D8 symbol in reporting groups the operational sources read for reports; it does not introduce an additional physical table.',
 '       The actor-specific arrows are essential to interpreting User Management and attendance correctly. An administrator’s profile-view query returns a read-only member profile. A member’s personal-change request affects only their own permitted personal details. Staff arrows identify counter and attendance operations and do not include a profile query or personal-detail edit. Internal writes caused by registration, renewal, or server-side account provisioning describe the effects of an authorized operation; they are not a grant of general editing access to the underlying table. Authentication, role checks, database policies, and authorized functions support these boundaries even when different operations use the same data store.',
 '       Processes 8.0 and 9.0 have distinct outputs. Generate Reports reads operational records to produce the selected report and its supported preview or export. Activity Logs reads previously recorded events and returns the administrator’s filtered results. Staff-account changes occur under User Management, and phone-pairing changes occur under QR Attendance administration. Their events may appear in the log, but the log viewer does not perform those changes. This separation prevents the model from treating monitoring an operation as permission to execute it.'
 )
}
if($t.StartsWith('Figure 4 distinguishes the Member')){
 Put $p '                Figure 4 describes the system from the perspective of the goals each actor is permitted to accomplish. The stick figures represent the Member / Applicant, Authorized Staff, and Administrator. The ellipses identify use cases, and the association lines connect an actor with the functions available to that role. The system boundary encloses the use cases while the actors remain outside it. Shared functions may appear in more than one role column for readability, but repeated labels refer to the same system capability rather than to separate implementations.'
 After $p @(
 '                Member and applicant use cases concern registration and personal self-service. An applicant submits an online application and checks its result, while a registered member retrieves their own membership information, displays their QR code, views their attendance history, browses active products, and requests renewal. Only the member can update their own permitted personal-profile details. The administrator’s View Member Profiles use case is therefore distinct from the member’s Update Own Profile use case: the administrator can inspect the information but cannot change the member’s personal details.',
 '                Staff use cases are limited to attendance and supported counter services. Walk-in registration creates a new account and member record through an authorized service; direct renewal and active-plan change record the selected membership transaction. These functions do not provide staff with a personal-profile screen or an existing-profile editing function. Staff product-sale recording and own-sales review likewise do not grant inventory-maintenance, report, or activity-log access. Administrator use cases cover online review, the permitted operational controls, staff-account administration, phone pairing, reports, and read-only activity-log review. The model describes implemented responsibilities rather than planned business notifications or customer receipt provision.'
 )
}
if($t.StartsWith('The physical ERD in Figure 5a-c')){
 Put $p 'The physical ERD in Figure 5a-c explains the relationships declared in the checked-in database migration baseline. It complements the DFD: the DFD shows how information is processed, whereas the ERD shows how stored records refer to one another. Each relationship row names the parent and child entity, identifies the referenced primary key and child foreign key, and states its cardinality and deletion rule. The panels repeat entity boxes where necessary to keep the relationships readable; repeated names denote the same physical table and should not be counted as additional tables.'
 After $p @(
 '            Cardinality describes the number of records permitted on either side of a relationship. A required foreign key means that a child record must reference one parent; a nullable foreign key permits the child to exist without that reference. A parent may generally be associated with multiple child records, although a primary key or unique index can restrict a relationship to at most one child. For example, a member may have many attendance records and membership-history events, while the linked Auth-account index permits at most one member record for a particular non-null Auth identifier. An optional sale member reference and an optional sale-line product reference must not be treated as mandatory links.',
 '            The core entities preserve different kinds of operational information. Membership applications retain submitted registration or renewal requests and their review status. Members retains the current member and membership values, while membership_history preserves relevant values before and after lifecycle events. Attendance stores visits and the separate operators for check-in and check-out. Sales stores transaction headers, and sale_items stores the individual product or membership charges. Product names and prices captured in sale lines support historical records even when the current catalog changes. The retained receipt_number field is documented as an internal transaction identifier rather than evidence that a customer receipt is issued.',
 '            The physical model also includes supporting account, phone-pairing, logging, and attendance-request storage. The dictionary distinguishes twelve public-schema tables from two private supporting tables; managed Auth internals are outside the application-owned table count. The retained mobile_attendance_scan_events table appears because it exists in the baseline, not because a corresponding review interface is available. Deletion rules follow the actual constraints: CASCADE removes dependent rows, SET NULL clears an optional reference, and RESTRICT or the default NO ACTION behavior can prevent a change that would break a relationship. Finally, a foreign-key relationship does not grant an actor permission to view or edit data. Administrator read-only profile viewing, member-only personal editing, and the staff profile restriction remain application authorization rules.'
 )
}
if($t.StartsWith('The Gantt chart presents the planned development schedule')){
 After $p @('            The horizontal timeline indicates when each planned activity was assigned, while the colored marks associate the activity rows with the corresponding week. The chart should be read as a schedule of intended work rather than as proof that an activity was completed on that date. Its planning, design, and development groups organize the original sequence of work; they do not replace the iterative refinement described in the Agile methodology. Since the system has subsequently changed, the chart’s dates are retained as the original plan and should be distinguished from any separately verified record of actual development or deployment.')
}
}
$e.Delete();$e=$z.CreateEntry('word/document.xml');$w=[IO.StreamWriter]::new($e.Open(),[Text.UTF8Encoding]::new($false));$w.Write($d.OuterXml);$w.Dispose()
"Shortened $count dictionary descriptions and expanded context, DFD, use-case, ERD, and schedule explanations."
} finally {$z.Dispose()}
